def iframe_src(value):
    text = clean(value)
    if '<' not in text:
        return ''
    match = re.search(r'\bsrc\s*=\s*["\']([^"\']+)["\']', text, re.I)
    if not match:
        return ''
    return match.group(1).replace('&amp;', '&').strip()

