def assets_from_payload(payload, imported_from='payload'):
    assets = []
    seen = set()
    for component, context in iter_components(payload):
        for asset in component_assets(component, context, payload, imported_from):
            if asset['id'] in seen:
                continue
            seen.add(asset['id'])
            assets.append(asset)
    return assets

